// frontend/src/App.jsx
// symbol: App

export default function App() {
  return (
    <Router>
      <Routes>
        {/* Home/Profile Selection */}
        <Route path="/" element={<ProfileSelectionPage />} />

        {/* Login Routes */}
        <Route path="/login" element={<LoginPage />} />

        {/* Feature-specific Routes */}
        {StudentRoutes}
        {TeacherRoutes}
        {AdminRoutes}

        {/* Fallback route */}
        <Route path="*" element={<NotFoundPage />} />
      </Routes>
    </Router>
