// Action types
type AuthAction =
  | { type: "AUTH_START" }
  | { type: "AUTH_SUCCESS"; payload: { user: User; token: string } }
  | { type: "AUTH_ERROR"; payload: string }
  | { type: "AUTH_LOGOUT" }
  | { type: "CLEAR_ERROR" }
  | { type: "SET_LOADING"; payload: boolean };

// apps/sketchxpad-frontend/src/contexts/AuthContext.tsx
// symbol: anonymous

const initialState: AuthState = {
  user: null,
  token: localStorage.getItem("token"),
  isLoading: false,
  isAuthenticated: false,
  error: null,
};

// apps/sketchxpad-frontend/src/contexts/AuthContext.tsx
// symbol: anonymous

const authReducer = (state: AuthState, action: AuthAction): AuthState => {
  switch (action.type) {
    case "AUTH_START":
      return {
        ...state,
        isLoading: true,
        error: null,
      };
    case "AUTH_SUCCESS":
      return {
        ...state,
        isLoading: false,
        isAuthenticated: true,
        user: action.payload.user,
        token: action.payload.token,
        error: null,
      };
    case "AUTH_ERROR":
      return {
        ...state,
        isLoading: false,
        isAuthenticated: false,
        user: null,
        token: null,
        error: action.payload,
      };
    case "AUTH_LOGOUT":
      return {
        ...state,
        isAuthenticated: false,
        user: null,
        token: null,
        error: null,
      };
    case "CLEAR_ERROR":
      return {
        ...state,
        error: null,
      };
    case "SET_LOADING":
      return {
        ...state,
        isLoading: action.payload,
      };
    default:
      return state;
  }
};

// apps/sketchxpad-frontend/src/contexts/AuthContext.tsx
// symbol: anonymous

const AuthContext = createContext<AuthContextType | undefined>(undefined);

// apps/sketchxpad-frontend/src/contexts/AuthContext.tsx
// symbol: anonymous

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const [state, dispatch] = useReducer(authReducer, initialState);

  // Axios interceptor for adding auth token
  useEffect(() => {
    const interceptor = axios.interceptors.request.use(
      (config) => {
        if (state.token) {
          config.headers.Authorization = `Bearer ${state.token}`;
        }
        return config;
      },
      (error) => Promise.reject(error)
    );

    return () => axios.interceptors.request.eject(interceptor);
  }, [state.token]);

  // Check token on app start
  useEffect(() => {
    const checkAuthStatus = async () => {
      const token = localStorage.getItem("token");
      if (token) {
        try {
          dispatch({ type: "SET_LOADING", payload: true });

          // Verify token with backend
          const response = await axios.get(`${HTTP_URL}/api/auth/me`, {
            headers: { Authorization: `Bearer ${token}` },
          });

          dispatch({
            type: "AUTH_SUCCESS",
            payload: {
              user: response.data.user,
              token: token,
            },
          });
        } catch (error) {
          // Token is invalid, remove it
          localStorage.removeItem("token");
          dispatch({ type: "AUTH_LOGOUT" });
        } finally {
          dispatch({ type: "SET_LOADING", payload: false });
        }
      }
    };

    checkAuthStatus();
  }, []);

  const login = async (email: string, password: string) => {
    try {
      dispatch({ type: "AUTH_START" });

      const response = await axios.post(`${HTTP_URL}/api/auth/signin`, {
        email,
        password,
      });

      const { token, user } = response.data;

      localStorage.setItem("token", token);

      dispatch({
        type: "AUTH_SUCCESS",
        payload: { user, token },
      });
    } catch (error: any) {
      const errorMessage = error.response?.data?.message || "Login failed";
      dispatch({ type: "AUTH_ERROR", payload: errorMessage });
      throw new Error(errorMessage);
    }
  };

  const signup = async (username: string, email: string, password: string) => {
    try {
      dispatch({ type: "AUTH_START" });

      const response = await axios.post(`${HTTP_URL}/api/auth/signup`, {
        name: username,
        email,
        password,
      });

      const { token, user } = response.data;

      localStorage.setItem("token", token);

      dispatch({
        type: "AUTH_SUCCESS",
        payload: { user, token },
      });
    } catch (error: any) {
      const errorMessage = error.response?.data?.message || "Signup failed";
      dispatch({ type: "AUTH_ERROR", payload: errorMessage });
      throw new Error(errorMessage);
    }
  };

  const logout = () => {
    localStorage.removeItem("token");
    dispatch({ type: "AUTH_LOGOUT" });
  };

  const clearError = () => {
    dispatch({ type: "CLEAR_ERROR" });
  };

  const value: AuthContextType = {
    ...state,
    login,
    signup,
    logout,
    clearError,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

// apps/sketchxpad-frontend/src/contexts/AuthContext.tsx
// symbol: anonymous

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
};

