def estimate_cost(input_tokens: int, output_tokens: int) -> float:
    """Estimate cost in USD for a given token count."""
    return (input_tokens * COST_PER_INPUT_TOKEN) + (output_tokens * COST_PER_OUTPUT_TOKEN)

# src/config.py
# symbol: get_text
# docstring: """Extract plain text from response content.
Handles string, lists, and dict format content safely."""

def get_text(content) -> str:
    """
    Extract plain text from response content.
    Handles string, lists, and dict format content safely.
    """
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict) and "text" in item:
                parts.append(item["text"])
            elif isinstance(item, str):
                parts.append(item)
        return "\n".join(parts)
    return str(content)

