# symbol: _invoke_with_retry
# docstring: """Call LLM with exponential backoff on rate limit errors."""

def _invoke_with_retry(llm, messages, max_retries=3):
    """Call LLM with exponential backoff on rate limit errors."""
    for attempt in range(max_retries):
        try:
            return llm.invoke(messages)
        except Exception as e:
            err_str = str(e)
            if "429" in err_str or "RESOURCE_EXHAUSTED" in err_str:
                wait = (2 ** attempt) + random.uniform(0.5, 2.0)
                print(f"   ⏳ Rate limit hit, waiting {wait:.1f}s (attempt {attempt+1}/{max_retries})")
                time.sleep(wait)
            else:
                raise  # Re-raise non-rate-limit errors
    raise RuntimeError(f"Max retries ({max_retries}) exceeded due to rate limiting")

# src/tools.py
# symbol: _arxiv_search
# docstring: """Search Arxiv using direct HTTP request with a timeout and XML parsing."""

def _arxiv_search(query: str) -> str:
    """Search Arxiv using direct HTTP request with a timeout and XML parsing."""
    try:
        url = "https://export.arxiv.org/api/query"
        params = {
            "search_query": query,
            "max_results": 3,
            "sortBy": "relevance",
            "sortOrder": "descending"
        }
        headers = {
            "User-Agent": "MultiSourceRAG/1.0 (contact@example.com)"
        }
        # Strict 10-second timeout to prevent indefinite hangs
        response = requests.get(url, params=params, headers=headers, timeout=10.0)

        if response.status_code != 200:
            return f"Arxiv search error: HTTP {response.status_code}. Arxiv API may be rate-limited or temporarily down."

        root = ET.fromstring(response.content)
        ns = {"atom": "http://www.w3.org/2005/Atom"}

        entries = root.findall("atom:entry", ns)
        if not entries:
            return "No Arxiv papers found for this query."

        parts = []
        for entry in entries:
            title_node = entry.find("atom:title", ns)
            title = title_node.text.strip() if title_node is not None else "Untitled"
            title = " ".join(title.split())

            published_node = entry.find("atom:published", ns)
            published = "Unknown"
            if published_node is not None and published_node.text:
                published = published_node.text[:10]  # Format: YYYY-MM-DD

            summary_node = entry.find("atom:summary", ns)
            summary = summary_node.text.strip() if summary_node is not None else ""
            summary = " ".join(summary.split())
            if len(summary) > 400:
                summary = summary[:400] + "..."

            id_node = entry.find("atom:id", ns)
            entry_id = id_node.text.strip() if id_node is not None else ""

            authors = []
            for author_node in entry.findall("atom:author", ns):
                name_node = author_node.find("atom:name", ns)
                if name_node is not None and name_node.text:
                    authors.append(name_node.text.strip())
            authors_str = ", ".join(authors[:3])

            parts.append(
                f"Title: {title}\n"
                f"Authors: {authors_str}\n"
                f"Published: {published}\n"
                f"Summary: {summary}\n"
                f"URL: {entry_id}"
            )
        return "\n\n---\n\n".join(parts)
    except requests.exceptions.Timeout:
        return "Arxiv search error: request timed out. Arxiv API is currently slow or unresponsive."
    except Exception as e:
        return f"Arxiv search error: {e}"

# src/tracking.py
# symbol: extract_token_usage
# docstring: """Extract (input_tokens, output_tokens) from an LLM response.
Handles both Groq (dict) and Gemini (object) usage_metadata formats.
Returns (0, 0) if metadata is unavailable."""

def extract_token_usage(llm_response) -> tuple[int, int]:
    """
    Extract (input_tokens, output_tokens) from an LLM response.
    Handles both Groq (dict) and Gemini (object) usage_metadata formats.
    Returns (0, 0) if metadata is unavailable.
    """
    try:
        usage = llm_response.usage_metadata
        if usage:
            # Groq returns a dict: {'input_tokens': N, 'output_tokens': N}
            if isinstance(usage, dict):
                inp = usage.get("input_tokens", 0)
                out = usage.get("output_tokens", 0)
            else:
                # Gemini returns an object with attributes
                inp = getattr(usage, "input_tokens", 0) or getattr(usage, "prompt_token_count", 0)
                out = getattr(usage, "output_tokens", 0) or getattr(usage, "candidates_token_count", 0)
            return int(inp), int(out)
    except Exception:
        pass
    return 0, 0
